 5	method binarySearch(v:array<int>, elem:int) returns (p:int)
 6	 requires sorted(v[0..v.Length])
 7	 ensures -1<=p<v.Length
 8	 ensures (forall u::0<=u<=p ==> v[u]<=elem) && (forall w::p<w<v.Length ==> v[w]>elem)
