11	  while (c<=f)
12	     decreases f-c
13	     invariant 0<=c<=v.Length && -1<=f<=v.Length-1 && c<=f+1
14	     invariant (forall u::0<=u<c ==> v[u]<=elem) && 
15	               (forall w::f<w<v.Length ==> v[w]>elem)
16	  {
17	   var m:=(c+f)/2;
18	   if (v[m]<=elem) 
19	        {c:=m+1;}
20	   else {f:=m-1;}
21	   }
22	   p:=c-1;
